'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s);
const TILE=24,N=26,SIZE=624,DIR=[[0,-1],[1,0],[0,1],[-1,0]],keys=new Set();
let map=[],player,enemies=[],bullets=[],particles=[],powerups=[],state='ready',level=1,score=0,lives=3,spawned=0,killed=0,spawnTimer=0,baseAlive=true,shield=0,upgrade=0,clock=0,last=0,sound=false,audioCtx,best=0;
try{best=Number(localStorage.getItem('tanki-best'))||0}catch{}$('#best').textContent=String(best).padStart(6,'0');
function beep(f,d=.07,type='square',volume=.025){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(f,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,f/3),audioCtx.currentTime+d);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d)}catch{}}
function hud(){ $('#score').textContent=String(score).padStart(6,'0');$('#lives').textContent='▰ '.repeat(Math.max(0,lives));$('#level').textContent=String(level).padStart(2,'0');$('#stage-label').textContent='ОПЕРАЦИЯ '+String(level).padStart(2,'0');$('.panel-heading span').textContent=String(level).padStart(2,'0')+' / ∞';$('#remaining').textContent=20-killed;$('#enemy-grid').innerHTML=Array.from({length:20},(_,i)=>'<span class="'+(i<killed?'dead':'')+'"></span>').join('');if(score>best){best=score;$('#best').textContent=String(best).padStart(6,'0');try{localStorage.setItem('tanki-best',best)}catch{}}$('.base-status').innerHTML='<span class="status-dot"></span> '+(baseAlive?'ШТАБ ПОД ЗАЩИТОЙ':'ШТАБ ПОТЕРЯН'); }
function createMap(){map=Array.from({length:N},()=>Array(N).fill(0));for(let y=2;y<22;y++){for(let x=2;x<24;x++){if((x%4===2||x%4===3)&&y%7<5)map[y][x]=1;}}for(let x=3;x<23;x++){if(x<10||x>15)map[12][x]=level%2?2:1;}for(let y=7;y<10;y++)for(let x=10;x<16;x++)map[y][x]=3;for(let y=16;y<19;y++)for(let x=10;x<16;x++)map[y][x]=4;for(let x=11;x<=14;x++){map[23][x]=1;map[25][x]=x===11||x===14?1:0;}map[24][11]=map[24][14]=1;map[24][12]=map[24][13]=5;map[25][12]=map[25][13]=5;for(let y=22;y<26;y++)for(let x=7;x<=9;x++)map[y][x]=0;}
function newPlayer(){player={x:8*TILE+3,y:24*TILE+3,w:36,h:36,dir:0,cd:0,moving:false};shield=3;}
function setup(){createMap();enemies=[];bullets=[];particles=[];powerups=[];spawned=0;killed=0;spawnTimer=.8;baseAlive=true;upgrade=0;newPlayer();hud();}
function start(){level=1;score=0;lives=3;setup();state='playing';$('#overlay').classList.add('hidden');$('#pause').textContent='Ⅱ ПАУЗА';beep(500,.15);canvas.focus();}
function showOverlay(title,text,button){$('#overlay-title').innerHTML=title;$('#overlay-text').innerHTML=text;$('#start').innerHTML=button+' <span>↗</span>';$('#overlay').classList.remove('hidden');}
function pause(){if(state==='playing'){state='paused';showOverlay('ПЕРЕДЫШКА.','Штаб подождёт. Возвращайся в бой.','ПРОДОЛЖИТЬ');$('#pause').textContent='▶ ПРОДОЛЖИТЬ';}else if(state==='paused'){state='playing';$('#overlay').classList.add('hidden');$('#pause').textContent='Ⅱ ПАУЗА';}}
function end(){state='over';showOverlay(baseAlive?'БОЙ ОКОНЧЕН.':'ШТАБ ПОТЕРЯН.','Твой счёт: '+score+'<br>Каждому командиру нужен второй шанс.','ЕЩЁ РАЗ');beep(100,.6,'sawtooth');hud();}
function solid(x,y,w,h,tank){if(x<0||y<0||x+w>SIZE||y+h>SIZE)return true;for(let yy=Math.floor(y/TILE);yy<=Math.floor((y+h-1)/TILE);yy++)for(let xx=Math.floor(x/TILE);xx<=Math.floor((x+w-1)/TILE);xx++){const t=map[yy]?.[xx];if(t===1||t===2||t===3||t===5)return true;}for(const other of [player,...enemies]){if(other!==tank&&overlap({x,y,w,h},other))return true;}return false;}
function overlap(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function move(t,d,amount){t.dir=d;const [dx,dy]=DIR[d],x=t.x+dx*amount,y=t.y+dy*amount;if(!solid(x,y,t.w,t.h,t)){t.x=x;t.y=y;t.moving=true;return true;}t.moving=false;return false;}
function shoot(t){if(t!==player||t.cd>0)return;const [dx,dy]=DIR[t.dir];bullets.push({x:t.x+t.w/2+dx*23-3,y:t.y+t.h/2+dy*23-3,w:6,h:6,dx,dy,enemy:false,heavy:upgrade>0});t.cd=upgrade?.22:.35;beep(630);}
function explode(x,y,color='#eec875',big=false){for(let i=0;i<(big?28:10);i++){const angle=Math.random()*Math.PI*2,speed=30+Math.random()*150;particles.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:.2+Math.random()*.4,color,size:big?5:3});}beep(big?90:220,big?.18:.05,'sawtooth');}
const SPECIES=[
{name:'Раптор',color:'#8eba65',hp:1,speed:110,bite:.85},
{name:'Тираннозавр',color:'#d89464',hp:3,speed:60,bite:1.25},
{name:'Трицератопс',color:'#9b94c5',hp:2,speed:78,bite:1.05}
];
function makeDino(x,y,kind){const species=SPECIES[kind];return {x,y,w:36,h:36,dir:2,cd:.5,think:0,hp:species.hp,speed:species.speed+level*3,kind,moving:false,biteAnim:0,waypoint:null};}
function spawn(){if(spawned>=20||enemies.length>=4)return;const positions=[6,294,582];for(let i=0;i<3;i++){const x=positions[(spawned+i)%3];if(!solid(x,6,36,36,null)){enemies.push(makeDino(x,6,spawned%3));spawned++;return;}}}
function distance(a,b){return Math.hypot(Math.max(a.x-b.x-b.w,b.x-a.x-a.w,0),Math.max(a.y-b.y-b.h,b.y-a.y-a.h,0));}
function route(e,target){
 const start=Math.floor((e.y+18)/48)*13+Math.floor((e.x+18)/48),goal=Math.min(168,Math.floor((target.y+target.h/2)/48)*13+Math.floor((target.x+target.w/2)/48));
 const costs=Array(169).fill(Infinity),prev=Array(169).fill(-1),visited=new Set();costs[start]=0;
 for(let n=0;n<169;n++){let current=-1;for(let i=0;i<169;i++)if(!visited.has(i)&&(current<0||costs[i]<costs[current]))current=i;if(current<0||!Number.isFinite(costs[current]))break;if(current===goal)break;visited.add(current);
 for(const [dx,dy] of DIR){const x=current%13+dx,y=Math.floor(current/13)+dy;if(x<0||y<0||x>=13||y>=13)continue;let cost=1,blocked=false;for(let yy=y*2;yy<y*2+2;yy++)for(let xx=x*2;xx<x*2+2;xx++){const t=map[yy][xx];if(t===2||t===3)blocked=true;if(t===1)cost+=2;}if(blocked)continue;const next=y*13+x;if(costs[current]+cost<costs[next]){costs[next]=costs[current]+cost;prev[next]=current;}}
 }
 if(start===goal)return {x:target.x+target.w/2-18,y:target.y+target.h/2-18};
 let next=goal;if(prev[next]<0)return null;while(prev[next]!==start&&prev[next]>=0)next=prev[next];
 // Align to the current corridor before turning into the next cell.
 const center={x:(start%13)*48+6,y:Math.floor(start/13)*48+6};
 if(Math.abs(e.x-center.x)>2&&Math.abs(e.y-center.y)>2)return center;
 if(next%13!==start%13&&Math.abs(e.y-center.y)>2)return center;
 if(Math.floor(next/13)!==Math.floor(start/13)&&Math.abs(e.x-center.x)>2)return center;
 return {x:(next%13)*48+6,y:Math.floor(next/13)*48+6};
}
function bite(e){if(e.cd>0)return;const base={x:288,y:576,w:48,h:48};let hit=false;
 if(distance(e,player)<=9){hit=true;if(shield<=0){explode(player.x+18,player.y+18,'#e7da7c',true);lives--;hud();if(lives<=0)end();else newPlayer();}}
 if(baseAlive&&distance(e,base)<=9){baseAlive=false;hit=true;explode(312,600,'#eed981',true);end();}
 const [dx,dy]=DIR[e.dir],jaw={x:e.x+dx*10,y:e.y+dy*10,w:36,h:36};
 if(!hit)for(let y=Math.max(0,Math.floor(jaw.y/24));y<=Math.min(25,Math.floor((jaw.y+35)/24));y++)for(let x=Math.max(0,Math.floor(jaw.x/24));x<=Math.min(25,Math.floor((jaw.x+35)/24));x++)if(map[y][x]===1){map[y][x]=0;hit=true;explode(x*24+12,y*24+12,'#9e7154');}
 if(hit){e.cd=SPECIES[e.kind].bite;e.biteAnim=.25;beep(140,.12,'sawtooth');}
}
function updateDino(e,dt){e.cd-=dt;e.biteAnim=Math.max(0,e.biteAnim-dt);e.think-=dt;const target=distance(e,player)<220?player:{x:288,y:576,w:48,h:48};if(e.think<=0){e.waypoint=route(e,target);e.think=.4;}
 e.moving=false;if(e.waypoint){const dx=e.waypoint.x-e.x,dy=e.waypoint.y-e.y;if(Math.abs(dx)>.8||Math.abs(dy)>.8){const horizontal=Math.abs(dx)>Math.abs(dy);const d=horizontal?(dx>0?1:3):(dy>0?2:0);move(e,d,Math.min(e.speed*dt,horizontal?Math.abs(dx):Math.abs(dy)));}else e.think=0;}bite(e);
}
function update(dt){clock+=dt;shield=Math.max(0,shield-dt);player.cd-=dt;player.moving=false;let d=-1;if(keys.has('ArrowUp')||keys.has('KeyW'))d=0;else if(keys.has('ArrowRight')||keys.has('KeyD'))d=1;else if(keys.has('ArrowDown')||keys.has('KeyS'))d=2;else if(keys.has('ArrowLeft')||keys.has('KeyA'))d=3;if(d>=0)move(player,d,145*dt);if(keys.has('Space'))shoot(player);spawnTimer-=dt;if(spawnTimer<=0){spawn();spawnTimer=1.7;}
for(const e of enemies){updateDino(e,dt);if(state!=='playing')return;}
for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];let hit=false;const steps=3;for(let step=0;step<steps&&!hit;step++){b.x+=b.dx*(b.enemy?235:360)*dt/steps;b.y+=b.dy*(b.enemy?235:360)*dt/steps;if(b.x<0||b.y<0||b.x>SIZE-6||b.y>SIZE-6){hit=true;break;}for(let y=Math.floor(b.y/24);y<=Math.floor((b.y+5)/24);y++)for(let x=Math.floor(b.x/24);x<=Math.floor((b.x+5)/24);x++){const tile=map[y]?.[x];if(tile===1||tile===2||tile===5){hit=true;if(tile===1||(tile===2&&b.heavy)){map[y][x]=0;explode(x*24+12,y*24+12,tile===1?'#9e7154':'#aeb9ac');}if(tile===5){baseAlive=false;explode(312,600,'#eed981',true);end();}}}if(hit)break;if(b.enemy){if(overlap(b,player)){hit=true;if(shield<=0){explode(player.x+18,player.y+18,'#e7da7c',true);lives--;hud();if(lives<=0)end();else newPlayer();}}}else{for(let j=enemies.length-1;j>=0;j--){const e=enemies[j];if(overlap(b,e)){hit=true;e.hp--;explode(e.x+18,e.y+18);if(e.hp<=0){explode(e.x+18,e.y+18,'#f2b76c',true);enemies.splice(j,1);killed++;score+=100;if(killed%5===0)powerups.push({x:e.x,y:e.y,w:28,h:28,life:15,type:killed%10===0?'life':'star'});hud();}break;}}}if(!hit){for(let j=0;j<bullets.length;j++){if(j!==i&&bullets[j].enemy!==b.enemy&&overlap(b,bullets[j])){bullets[j].dead=true;hit=true;break;}}}}if(hit||b.dead)bullets.splice(i,1);}
for(let i=powerups.length-1;i>=0;i--){const p=powerups[i];p.life-=dt;if(overlap(p,player)){if(p.type==='life')lives++;else upgrade=1;score+=500;beep(900,.2);hud();powerups.splice(i,1);}else if(p.life<=0)powerups.splice(i,1);}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.life<=0)particles.splice(i,1);}if(killed>=20&&enemies.length===0&&state==='playing'){state='transition';$('#toast').textContent='ОПЕРАЦИЯ ВЫПОЛНЕНА';$('#toast').style.display='block';setTimeout(()=>{if(state!=='transition')return;level++;score+=1000;setup();state='playing';$('#toast').style.display='none';},1800);}}
function tank(t,color){ctx.save();ctx.translate(Math.round(t.x+18),Math.round(t.y+18));ctx.rotate(t.dir*Math.PI/2);ctx.fillStyle='#11160f';ctx.fillRect(-18,-18,10,36);ctx.fillRect(8,-18,10,36);ctx.fillStyle=color;ctx.fillRect(-17,-17,7,34);ctx.fillRect(10,-17,7,34);ctx.fillStyle='#1e2518';for(let y=-15;y<18;y+=7){const offset=t.moving?Math.floor(clock*12)%2*2:0;ctx.fillRect(-17,y+offset,7,3);ctx.fillRect(10,y+offset,7,3);}ctx.fillStyle=color;ctx.fillRect(-9,-13,18,27);ctx.fillStyle='#ffffff30';ctx.fillRect(-8,-12,4,24);ctx.fillStyle='#262e1f';ctx.fillRect(-6,-7,12,16);ctx.fillStyle=color;ctx.fillRect(-4,-6,9,11);ctx.fillRect(-3,-24,6,21);ctx.fillStyle='#ffffff45';ctx.fillRect(-3,-24,2,16);ctx.restore();}
function dinosaur(e){
 const kind=e.kind??0,species=SPECIES[kind],step=e.moving?Math.sin(clock*16)*3:0,bite=e.biteAnim>0;
 ctx.save();ctx.translate(Math.round(e.x+18),Math.round(e.y+18));ctx.rotate(e.dir*Math.PI/2);
 ctx.fillStyle='#0c120b';ctx.fillRect(-15,-15,30,34);
 // Tail, alternating legs, body and a distinct head for each species.
 ctx.fillStyle=species.color;ctx.fillRect(-4,12,8,10);ctx.fillRect(-2,21,4,5);
 ctx.fillRect(-15,-1+step,7,12);ctx.fillRect(8,2-step,7,12);ctx.fillRect(-11,-8,22,24);
 ctx.fillStyle='#ffffff22';ctx.fillRect(-8,-6,5,18);
 ctx.fillStyle=species.color;
 if(kind===0){ctx.fillRect(-7,-20,14,18);ctx.fillRect(-6,-25,12,9);ctx.fillRect(-17,-7,6,4);ctx.fillRect(11,-7,6,4);ctx.fillStyle='#446b39';ctx.fillRect(-2,-10,4,26);}
 if(kind===1){ctx.fillStyle='#b96d4d';ctx.fillRect(-13,-17,26,12);ctx.fillStyle=species.color;ctx.fillRect(-12,-25,24,18);ctx.fillRect(-15,-2,5,5);ctx.fillRect(10,-2,5,5);ctx.fillStyle='#f7e6bd';ctx.fillRect(-10,-19,20,3);}
 if(kind===2){ctx.fillStyle='#70688e';ctx.fillRect(-17,-15,34,15);ctx.fillRect(-13,-19,26,8);ctx.fillStyle=species.color;ctx.fillRect(-9,-24,18,18);ctx.fillStyle='#eee0b7';ctx.fillRect(-12,-28,5,12);ctx.fillRect(7,-28,5,12);ctx.fillRect(-2,-30,4,8);}
 ctx.fillStyle='#f5edc6';ctx.fillRect(-8,-21,4,4);ctx.fillRect(4,-21,4,4);ctx.fillStyle='#20291b';ctx.fillRect(-7,-21,2,2);ctx.fillRect(5,-21,2,2);
 if(bite){ctx.fillStyle='#281c17';ctx.fillRect(-7,-26,14,8);ctx.fillStyle='#fff0c6';for(let x=-6;x<7;x+=5){ctx.fillRect(x,-26,3,3);ctx.fillRect(x,-21,3,3);}ctx.strokeStyle='#f1d48a';ctx.lineWidth=2;ctx.strokeRect(-20,-34,40,42);}
 ctx.restore();
}
function tile(t,x,y){if(t===1){ctx.fillStyle='#896448';ctx.fillRect(x,y,24,24);ctx.fillStyle='#a97d58';ctx.fillRect(x+1,y+1,22,9);ctx.fillRect(x+1,y+13,10,9);ctx.fillRect(x+13,y+13,10,9);ctx.fillStyle='#513f2e';ctx.fillRect(x,y+10,24,2);ctx.fillRect(x+11,y+12,2,12);ctx.fillRect(x+4,y,2,10);}else if(t===2){ctx.fillStyle='#738071';ctx.fillRect(x,y,24,24);ctx.fillStyle='#a0ab97';ctx.fillRect(x+2,y+2,20,3);ctx.fillRect(x+2,y+2,3,20);ctx.fillStyle='#475442';ctx.fillRect(x+21,y+4,3,20);ctx.fillRect(x+4,y+21,20,3);ctx.fillStyle='#84927e';ctx.fillRect(x+6,y+6,12,12);}else if(t===3){ctx.fillStyle='#253c3a';ctx.fillRect(x,y,24,24);ctx.fillStyle='#3b5550';ctx.fillRect(x+3+(Math.floor(clock*2)%2)*3,y+6,13,2);ctx.fillRect(x+9,y+17,12,2);}else if(t===4){ctx.fillStyle='#3a4b2d';ctx.fillRect(x+1,y+1,22,22);ctx.fillStyle='#53633b';for(let i=0;i<4;i++)ctx.fillRect(x+(i*7)%19,y+(i*11)%20,8,5);}}
function draw(){ctx.fillStyle='#141b12';ctx.fillRect(0,0,SIZE,SIZE);ctx.fillStyle='#1b2417';for(let y=0;y<26;y++)for(let x=0;x<26;x++){if((x+y)%3===0)ctx.fillRect(x*24+9,y*24+7,2,2);const t=map[y]?.[x];if(t&&t!==4&&t!==5)tile(t,x*24,y*24);}if(baseAlive){ctx.fillStyle='#c1b886';ctx.fillRect(292,580,40,40);ctx.fillStyle='#252c1d';ctx.fillRect(295,583,34,34);ctx.fillStyle='#c1b886';ctx.fillRect(308,589,8,22);ctx.fillRect(298,588,7,14);ctx.fillRect(319,588,7,14);ctx.fillRect(303,597,18,8);ctx.fillRect(304,611,16,3);ctx.fillRect(312,586,8,5);}
for(const e of enemies)dinosaur(e);if(player){tank(player,upgrade?'#f3d383':'#cbd77a');if(shield>0&&Math.floor(clock*10)%2===0){ctx.strokeStyle='#e7edac';ctx.lineWidth=2;ctx.strokeRect(player.x-4,player.y-4,44,44);}}for(let y=0;y<N;y++)for(let x=0;x<N;x++)if(map[y]?.[x]===4)tile(4,x*24,y*24);for(const p of powerups){if(p.life<4&&Math.floor(clock*7)%2)continue;ctx.fillStyle='#b9ce76';ctx.fillRect(p.x,p.y,28,28);ctx.fillStyle='#27351c';ctx.font='23px monospace';ctx.fillText(p.type==='life'?'+':'★',p.x+3,p.y+23);}for(const b of bullets){ctx.fillStyle=b.enemy?'#f2ac76':'#f1edb8';ctx.fillRect(Math.round(b.x),Math.round(b.y),6,6);}for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*4);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);}ctx.globalAlpha=1;ctx.fillStyle='#0000000e';for(let y=0;y<SIZE;y+=4)ctx.fillRect(0,y,SIZE,1);}
function frame(t){const dt=Math.min((t-last)/1000,.033);last=t;if(state==='playing')update(dt);draw();requestAnimationFrame(frame);}
$('#start').onclick=()=>state==='paused'?pause():start();$('#pause').onclick=pause;$('#restart').onclick=start;function toggleSound(){sound=!sound;$('#sound').textContent='ЗВУК: '+(sound?'ВКЛ':'ВЫКЛ');$('#sound').setAttribute('aria-label',sound?'Выключить звук':'Включить звук');if(sound)beep(600,.1);}$('#sound').onclick=toggleSound;
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Enter'){if(state==='ready'||state==='over')start();else if(state==='paused')pause();}if(e.code==='KeyP'||e.code==='Escape')pause();if(e.code==='KeyM')toggleSound();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(state==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause();});document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.key));});setup();enemies=[makeDino(6,6,0),makeDino(294,6,1),makeDino(582,6,2)];requestAnimationFrame(frame);
